-- 097: Source-backed curation for Bartın and Tekirdağ.
UPDATE public.places SET short_description='Amasra’nın Boztepe ve Zindan mahallelerini birleştiren Kemere Köprüsü çevresindeki tarihî savunma yapısı.', long_description='Amasra Kalesi iki ana bölümden oluşur: Boztepe’deki Sormagir ve Zindan Mahallesi’ndeki kale bölümü. Sur ve geçitleri kentin Roma, Bizans ve Ceneviz dönemlerine uzanan tarihini yansıtır.', source_url='https://bartin.ktb.gov.tr/TR-69008/amasra-kalesi.html', verified=true, trust_score=96, content_review_status='source_backed', updated_at=now() WHERE city='Bartın' AND slug='osm-node-11581658138';
UPDATE public.places SET short_description='Amasra ve çevresinden gelen Helenistik, Roma, Bizans, Ceneviz ve Osmanlı dönemlerine ait arkeolojik ve etnografik eserleri sergileyen müze.', long_description='Amasra Müzesi, arkeolojik ve etnografik eser salonlarında bölgenin uzun tarihini tanıtır. Müze binası 19. yüzyılda denizcilik okulu olarak tasarlanmış tarihî bir yapıdır.', source_url='https://bartin.ktb.gov.tr/TR-69003/amasra-muzesi.html', verified=true, trust_score=96, content_review_status='source_backed', updated_at=now() WHERE city='Bartın' AND slug='osm-way-370875212';
UPDATE public.places SET short_description='Bartın’ın tarihini, coğrafyasını, geleneksel zanaatlarını, mimarisini ve gündelik yaşamını anlatan kent müzesi.', long_description='Bartın Kent Müzesi, kentin tarihini kronolojik anlatımla sunar; gemi yapımcılığı, ticaret, mimari, kültür, basın ve ev yaşamı gibi başlıklara yer verir.', source_url='https://bartin.ktb.gov.tr/TR-69023/muzeler-ve-orenyerleri.html', verified=true, trust_score=94, content_review_status='source_backed', updated_at=now() WHERE city='Bartın' AND slug='osm-way-1151210000';
UPDATE public.places SET short_description='Yaklaşık 80 milyon yıllık olduğu tahmin edilen lav sütunları ve kıyı yürüyüş yolu ile tanınan doğal alan.', long_description='Güzelcehisar Lav Sütunları, Bartın kıyısında deniz boyunca uzanan volkanik kaya oluşumlarıdır. Ahşap yürüyüş yolu ve seyir noktaları kıyı peyzajını gözlemlemeye imkân verir.', source_url='https://bartin.ktb.gov.tr/TR-69018/guzelcehisar-lav-sutunlari.html', verified=true, trust_score=96, content_review_status='source_backed', updated_at=now() WHERE city='Bartın' AND slug='osm-way-1303441660';
UPDATE public.places SET short_description='Roma döneminden kalma, Amasra çevresindeki antik yol üzerinde kaya yüzeyine işlenmiş anıt.', long_description='Kuşkayası Yol Anıtı, Amasra yakınında Roma döneminde yapılmış kaya anıtıdır ve Bartın’ın öne çıkan arkeolojik miras noktalarından biridir.', source_url='https://bartin.ktb.gov.tr/TR-69031/yapmadan-donme.html', verified=true, trust_score=94, content_review_status='source_backed', updated_at=now() WHERE city='Bartın' AND slug='osm-node-5014697485';
UPDATE public.places SET short_description='Bartın ve Kastamonu sınırlarında uzanan, orman ekosistemleri ve karstik peyzajıyla öne çıkan korunan doğal alan.', long_description='Küre Dağları Millî Parkı, Batı Karadeniz’in ormanları ve doğal peyzajını korur. Ziyaret planında parkur, hava ve mevsim koşulları dikkate alınmalıdır.', source_url='https://bartin.ktb.gov.tr/TR-69013/gezilecek-yerler.html', verified=true, trust_score=92, content_review_status='source_backed', updated_at=now() WHERE city='Bartın' AND slug='osm-relation-1715618';
UPDATE public.places SET is_active=false, content_review_status='rejected', updated_at=now() WHERE city='Bartın' AND slug='osm-node-12310631699' AND EXISTS(SELECT 1 FROM public.places p WHERE p.city='Bartın' AND p.slug='osm-way-1151210000' AND p.is_active=true);
UPDATE public.places SET is_active=false, content_review_status='rejected', updated_at=now() WHERE city='Bartın' AND slug IN ('osm-way-997818674','osm-node-13869670173','osm-way-1409177578','osm-node-6391524213','osm-way-243643964') AND is_active=true;
UPDATE public.places SET short_description='Tekirdağ’ın arkeolojik ve etnografik mirasını, çevredeki antik yerleşimlerden getirilen buluntularla tanıtan müze.', long_description='Tekirdağ Müzesi, arkeolojik eserler, etnografya ve açık hava taş eserleri bölümlerinde bölgenin tarihini farklı dönemler boyunca sergiler.', source_url='https://tekirdag.ktb.gov.tr/TR-75776/tekirdag-muzesi.html', verified=true, trust_score=95, content_review_status='source_backed', updated_at=now() WHERE city='Tekirdağ' AND slug='osm-node-5806715469';
INSERT INTO public.places (name,category,city,address,latitude,longitude,slug,short_description,long_description,source_url,external_source,external_id,verified,trust_score,is_active,content_review_status,tags,updated_at)
SELECT s.name,s.category,s.city,s.address,s.latitude,s.longitude,s.slug,s.short_description,s.long_description,s.source_url,'curated_seed',s.slug,true,94,true,'source_backed',jsonb_build_array(s.category,s.city),now()
FROM (VALUES
('Rakoczi Müzesi','Müze ve kültür','Tekirdağ','Ertuğrul Mahallesi, Hikmet Çevik Sokak',40.9780,27.5235,'tekirdag-rakoczi-muzesi','Macar bağımsızlık hareketinin önderi II. Ferenc Rákóczi’nin Tekirdağ’da yaşadığı tarihî evde kurulan müze.','Rakoczi Müzesi, II. Ferenc Rákóczi’nin sürgün yıllarında yaşadığı tarihî Türk evinde yer alır; Türk-Macar ilişkileri ve Rákóczi ailesine ait eşyalar sergilenir.','https://tekirdag.ktb.gov.tr/TR-75777/rakoczi-muzesi.html'),
('Namık Kemal Evi','Müze ve kültür','Tekirdağ','Ortacami Mahallesi, Namık Kemal Caddesi',40.9760,27.5120,'tekirdag-namik-kemal-evi','Vatan şairi Namık Kemal’in hatırasını yaşatan ve geleneksel Tekirdağ ev düzenini tanıtan müze evi.','Namık Kemal Evi, şairin doğduğu evin çevresindeki eski Tekirdağ evleri örnek alınarak oluşturulmuştur; yöresel ev yaşamı ve Namık Kemal’e ilişkin eserler sergilenir.','https://tekirdag.ktb.gov.tr/TR-75778/namik-kemal-evi.html')
) AS s(name,category,city,address,latitude,longitude,slug,short_description,long_description,source_url)
WHERE NOT EXISTS (SELECT 1 FROM public.places p WHERE p.slug=s.slug)
AND NOT EXISTS (SELECT 1 FROM public.places p WHERE p.city=s.city AND lower(trim(p.name))=lower(trim(s.name)));
